review=[];actions=[]
categories=['OWNER_PROGRAM','ARCHITECT_1529_DIMENSIONS','PLUMBING_WATERPROOF_SUBMITTAL','TILE_MAKER_LAB_AND_1TO1','ESTIMATOR_SUPPLIER_RELEASE']
for item in rooms:
 rid=item['id'];d=data[rid];basis=Decimal(str(item['carried_quote_material_subtotal_usd_per_unit']))
 review.append(dict(room=rid,current_board_status=item['status'],current_champion=item['champion_id'] or '',prior_weighted_score=item['champion_score'] if item['champion_score'] is not None else '',historical_material_usd_copy=str(basis),historical_material_usd_two_copies=str(basis*2),exact_selected_program_and_fixture=d['program'],GOOD_unapproved_scope=d['good'],BETTER_unapproved_scope=d['better'],BEST_unapproved_scope=d['best'],owner_election_not_yet_made=d['decision'],individual_maker_wet_and_lab_gate=d['maker'],physical_exact_sample_kit_required=d['sample'],three_distinct_camera_visual_truth_instructions=d['three_views'],owner_approved_selected_tier='',current_verified_Chicago_material_quote='',current_installed_GC_bid='',one_time_waste_already_in_historic_gross='TRUE',owner_signature='FALSE',architect_signature='FALSE',plumbing_signature='FALSE',GC_signature='FALSE',purchasing_release='FALSE'))
 for cat in categories:
  if cat=='OWNER_PROGRAM':
   trade='OWNER'; req=d['decision'];pass_rule='Owner dated signature identifies exact room/program, true tile/fixture finish and selected GOOD/BETTER/BEST, separate material allowance and upgrade cap; source option text alone not approval.'
  elif cat=='ARCHITECT_1529_DIMENSIONS':
   trade='ARCHITECT + GC SURVEYOR';req='Verify native actual 1529 room identity, source W1/W2/W3 only where actually present, openings and level/pan net and floor threshold; tailor to '+d['program'];pass_rule='1529 model identity and on-site dimensions signed with control datum, selected wall measured/calibrated cut and niche opening/back/returns counted once; open model 1527 not sufficient.'
  elif cat=='PLUMBING_WATERPROOF_SUBMITTAL':
   trade='PLUMBER + WATERPROOF INSTALLER';req='Exact selected fixture/rough and program: '+d['program'];pass_rule='Factory trim-to-rough/waste/overflow and waterproof approved physical section, correct tub vs POINT vs LINEAR vs DRY vs WC. No shower PAN/flood if tub/dry/WC. Original drain never tub waste.'
  elif cat=='TILE_MAKER_LAB_AND_1TO1':
   trade='ARCHITECT + TILE INSTALLER';req=d['maker']+' Physical sample: '+d['sample'];pass_rule='For each applicable bath exact original measured numeric wet LEVEL and independent POINT/LINEAR PAN lab + exact WALL/NICHE wet factory listing; for dry/WC N/A or inherited parent; 1:1 approved true cuts, trim and movement.'
  else:
   trade='GC ESTIMATOR + SUPPLIER DOCUMENTS + PURCHASER';req='Reconcile original material-only $'+str(basis)+'/copy and two copies with branch-specific measured NET and once-only waste and verified same-lot case, total current Chicago installed offer; supplier outreach forbidden now.';pass_rule='Exact current supplier document, case coverage, lot/stock/ETA, freight/tax, installed bid, owner cap, 65 trade closures and separately signed PO authority; until then status FALSE.'
  actions.append(dict(room=rid,trade_class=cat,responsible_party=trade,specific_submittal_request=req,acceptance_evidence=pass_rule,actual_1529_source_document_or_site_witness='',signed_completion='',acceptance='FALSE',owner_release='FALSE',architect_release='FALSE',GC_release='FALSE',procurement_release='FALSE'))
assert len(review)==13 and len(actions)==65

def put(p,records):
 with (O/p).open('w',encoding='utf-8',newline='') as f:
  writer=csv.DictWriter(f,fieldnames=list(records[0]),lineterminator='\n');writer.writeheader();writer.writerows(records)
put('R24_13_ROOM_GOOD_BETTER_BEST_DELTA_AND_SIGNATURE_DECISIONS.csv',review)
put('R24_65_ROOM_SPECIFIC_ACCEPTANCE_RFI_AND_RELEASE_GATES.csv',actions)

lines=['# R24 — 13-room integrated owner Good / Better / Best material and field-decision directions','','**As of 2026-11-06: UNAPPROVED owner architectural directions, NOT a priced BOQ, selected substitute, board-scored champion or procurement release.** Good retains historical evidence and explicitly FAILS wet gates where unproven; Better introduces a new tested-scope alternative but is not automatically purchasable; Best is a conditional complete physical acceptance package (not evidence that a test occurred). All previously signed R12–R23 work untouched.','', '14 prior listing entries correspond to **nine independent buildings**, 405 W Armitage OT01–OT04 ONE Old Town reference. Old Town is primary, Lincoln Park/Gold Coast secondary/adjacent; PH ~$2.8M, TX ~$2.7M, target comp ~$2.4M–$3.2M. No authenticated competitor tile photos or current fresh supplier stock; no claims inferred from photographs.','']
for row in review:
 lines.extend(['## '+row['room']+' — '+row['current_board_status']+' / '+(row['current_champion'] or 'null'),'',f"Original dated 2026-09-03 tile-material reference: **${row['historical_material_usd_copy']}/copy**, two physical copies **${row['historical_material_usd_two_copies']}** (already includes original 15% gross waste once; not current installed price).",'', '**Controlling physical program:** '+row['exact_selected_program_and_fixture'],'','**GOOD — quote/source/owner status, failures explicit:** '+row['GOOD_unapproved_scope'],'','**BETTER — maker-specific, unselected technical improvement:** '+row['BETTER_unapproved_scope'],'','**BEST — owner/GC physical-evidence closure:** '+row['BEST_unapproved_scope'],'','**Decision owner must sign:** '+row['owner_election_not_yet_made'],'','**Individual maker wet and laboratory limits:** '+row['individual_maker_wet_and_lab_gate'],'','**1:1 physical sample/field section:** '+row['physical_exact_sample_kit_required'],'','**Three source-faithful views (not rendered/executed):** '+row['three_distinct_camera_visual_truth_instructions'],'','**Release:** owner FALSE, architect FALSE, plumber FALSE, GC FALSE, purchase FALSE; exact raw wet numeric floor/pan and actual current Chicago bid unknown unless N/A/inherited above.',''])
lines.extend(['## Decision sequence / stop rules','', 'The owner chooses program and design tier, the architect verifies actual 1529 geometry, plumber and waterproofing installer submit original factory exact assembly and drain/rough shop, installer proves individual WALL/NICHE wet uses and separately original raw numeric LEVEL/PAN wet tests where applicable, 1:1 material/cut/mockup is signed, estimator produces measured NET with only once-approved new waste and verified supplier carton/stock/installed Chicago bid, then owner/architect/GC/purchaser independently authorize any actual PO. No skipped gate becomes PASS because an option reads attractive.','', 'No additional Primary shower niche. PH and TX WC parent LEVEL once. No PAN in three tub rooms, wood-floor powders or shared WCs. Both Bath3 choices remain unsigned, square shower point drains cannot be tub wastes. PH4 remains walk-in 4-in BNX square point. AXOR 48140991 and Hansgrohe 32526141 are two distinct trims; 32526141 is NOT AXOR rough. TX Powder2 Tecturis 73072341 stays DECK, basin unselected.',''])
path=O/'R24_13_ROOM_OWNER_DESIGN_TIER_BOOK.md'
path.write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('PASS R24 authored thirteen distinct GOOD/BETTER/BEST owner alternatives and 65 new individual trade acceptance/test clauses, all release FALSE')
